function Write-SysLog {
    param(
        [string]$Message,
        [string]$Level   = 'INFO',
        [string]$LogPath = "$env:TEMP\DSI_SysLog.txt"
    )
    $ts    = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
    $entry = "[$ts] [$Level] $Message"
    $color = switch ($Level) {
        'ERROR' { 'Red'     }
        'WARN'  { 'Yellow'  }
        'AUDIT' { 'Cyan'    }
        default { 'Green'   }
    }
    Write-Host $entry -ForegroundColor $color
    Add-Content -Path $LogPath -Value $entry -Encoding UTF8
}

public static void WriteLog(string message, string level = "INFO") {
    string ts    = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
    string entry = $"[{ts}] [{level}] {message}";
    ConsoleColor color = level switch {
        "ERROR" => ConsoleColor.Red,
        "WARN"  => ConsoleColor.Yellow,
        "AUDIT" => ConsoleColor.Cyan,
        _       => ConsoleColor.Green
    };
    Console.ForegroundColor = color;
    Console.WriteLine(entry);
    Console.ResetColor();
    string logPath = Path.Combine(Path.GetTempPath(), "DSI_SysLog.txt");
    File.AppendAllText(logPath, entry + Environment.NewLine);
}

function Invoke-SecureRemoteCommand {
 param([string]$ComputerName, [string]$ScriptBlock, [PSCredential]$Credential, [switch]$AuditLog)
 $sb = [ScriptBlock]::Create($ScriptBlock)
 $params = @{ ComputerName = $ComputerName; ScriptBlock = $sb; ErrorAction = 'Stop' }
 if ($Credential) { $params['Credential'] = $Credential }
 try {
  $result = Invoke-Command @params
  if ($AuditLog) { Write-SysLog -Message "EXEC_REMOTE: $ComputerName | User: $env:USERNAME | Cmd: $ScriptBlock" -Level 'AUDIT' }
  return $result
 } catch {
  Write-SysLog -Message "ECHEC_EXEC_REMOTE: $ComputerName | Erreur: $_" -Level 'ERROR'
  throw
 }
}

function Audit-RemoteLogonSessions {
 param([string]$ComputerName, [switch]$IncludeHidden)
 $query = "Select * from Win32_LogonSession"
 $sessions = Get-CimInstance -ComputerName $ComputerName -Query $query -ErrorAction Stop
 $results = foreach ($s in $sessions) {
  if ($s.LogonType -in (2,3,10) -or $IncludeHidden) {
   $user = Get-CimAssociatedInstance -InputObject $s -ResultClassName Win32_Account
   [PSCustomObject]@{ Computer=$ComputerName; User=$user.Name; LogonType=$s.LogonType; StartTime=$s.StartTime }
  }
 }
 return $results
}

function Copy-FileToRemoteAdminShare {
 param([string]$LocalPath, [string]$RemoteComputer, [string]$RemotePath, [switch]$VerifyHash)
 $uncPath = "\\$RemoteComputer\$RemotePath"
 try {
  Copy-Item -Path $LocalPath -Destination $uncPath -Force -ErrorAction Stop
  if ($VerifyHash) {
   $hashLocal = (Get-FileHash -Path $LocalPath -Algorithm SHA256).Hash
   $hashRemote = Invoke-Command -ComputerName $RemoteComputer -ScriptBlock { param($p) (Get-FileHash -Path $p -Algorithm SHA256).Hash } -ArgumentList "C:\${RemotePath}" 
   if ($hashLocal -ne $hashRemote) { throw "Mismatch de hash SHA256" }
  }
  Write-SysLog -Message "COPIE_OK: $LocalPath -> $uncPath" -Level 'INFO'
  return $true
 } catch {
  Write-SysLog -Message "ECHEC_COPIE: $uncPath | $_" -Level 'ERROR'
  return $false
 }
}

function Get-RemoteScheduledTasks {
 param([string]$ComputerName, [string]$FilterPattern = "powershell|cmd|exe|bat")
 $tasks = Get-ScheduledTask -CimSession $ComputerName -ErrorAction SilentlyContinue
 $suspicious = foreach ($t in $tasks) {
  $info = Get-ScheduledTaskInfo -InputObject $t
  $action = $t.Actions.Execute
  if ($action -match $FilterPattern) {
   [PSCustomObject]@{ TaskName=$t.TaskName; Path=$t.TaskPath; Execute=$action; Arguments=$t.Actions.Arguments; LastRun=$info.LastRunTime; State=$t.State }
  }
 }
 return $suspicious
}

function Check-RemoteWinRMConfig {
 param([string]$ComputerName)
 try {
  $winrm = Invoke-Command -ComputerName $ComputerName -ScriptBlock { winrm get winrm/config }
  $listener = Invoke-Command -ComputerName $ComputerName -ScriptBlock { winrm enumerate winrm/config/listener }
  return [PSCustomObject]@{ Computer=$ComputerName; WinRMActive=$true; Config=$winrm; Listeners=$listener }
 } catch {
  return [PSCustomObject]@{ Computer=$ComputerName; WinRMActive=$false; Error=$_.Exception.Message }
 }
}

public static List<Dictionary<string, string>> ExecuteRemoteWMI(string computerName, string wmiQuery, string namespace = @"root\cimv2", int timeoutSeconds = 30) {
 var results = new List<Dictionary<string, string>>();
 var scope = new ManagementScope($"\\\\{computerName}\\{namespace}");
 scope.Options.Timeout = new TimeSpan(0, 0, timeoutSeconds);
 scope.Connect();
 var query = new ObjectQuery(wmiQuery);
 using var searcher = new ManagementObjectSearcher(scope, query);
 foreach (ManagementObject obj in searcher.Get()) {
  var dict = new Dictionary<string, string>();
  foreach (var prop in obj.Properties) {
   dict[prop.Name] = prop.Value?.ToString() ?? "";
  }
  results.Add(dict);
 }
 return results;
}

function Audit-RemoteLocalAdmins {
 param([string[]]$ComputerList, [string[]]$ExpectedAdmins = @('DOMAIN\Admins_SI'))
 $anomalies = @()
 foreach ($pc in $ComputerList) {
  try {
   $members = Invoke-Command -ComputerName $pc -ScriptBlock { Get-LocalGroupMember -Group 'Administrators' } -ErrorAction Stop
   foreach ($m in $members) {
    if ($m.Name -notin $ExpectedAdmins) {
     $anomalies += [PSCustomObject]@{ Computer=$pc; RogueAdmin=$m.Name; PrincipalSource=$m.PrincipalSource }
     Write-SysLog -Message "ALERTE: Admin local non autorisé sur $pc : $($m.Name)" -Level 'WARN'
    }
   }
  } catch { Write-SysLog -Message "Erreur audit $pc : $_" -Level 'ERROR' }
 }
 return $anomalies
}

function Get-RemoteEventLogSecurity {
 param([string]$ComputerName, [int]$HoursBack = 24, [int[]]$EventIDs = @(4624, 4648, 4672, 7045))
 $startTime = (Get-Date).AddHours(-$HoursBack)
 $filter = @{ LogName = 'Security'; Id = $EventIDs; StartTime = $startTime }
 Get-WinEvent -ComputerName $ComputerName -FilterHashtable $filter -ErrorAction SilentlyContinue | Select-Object TimeCreated, Id, @{Name='User';Expression={$_.Properties[5].Value}}, @{Name='Target';Expression={$_.Properties[6].Value}}, Message
}

public static Dictionary<string, string> RemoteServiceController(string computerName, string serviceName, string action) {
 var result = new Dictionary<string, string>();
 try {
  using var sc = new ServiceController(serviceName, computerName);
  result["Service"] = serviceName;
  result["CurrentStatus"] = sc.Status.ToString();
  if (action.Equals("Start", StringComparison.OrdinalIgnoreCase) && sc.Status != ServiceControllerStatus.Running) {
   sc.Start(); sc.WaitForStatus(ServiceControllerStatus.Running, TimeSpan.FromSeconds(30));
   result["Action"] = "Started";
  } else if (action.Equals("Stop", StringComparison.OrdinalIgnoreCase) && sc.Status != ServiceControllerStatus.Stopped) {
   sc.Stop(); sc.WaitForStatus(ServiceControllerStatus.Stopped, TimeSpan.FromSeconds(30));
   result["Action"] = "Stopped";
  } else {
   result["Action"] = "NoAction";
  }
 } catch (Exception ex) {
  result["Error"] = ex.Message;
 }
 return result;
}

function Test-RemoteRDPAccess {
 param([string]$ComputerName, [int]$Port = 3389)
 $tcp = Test-NetConnection -ComputerName $ComputerName -Port $Port -WarningAction SilentlyContinue
 $svc = Get-Service -ComputerName $ComputerName -Name 'TermService' -ErrorAction SilentlyContinue
 $reg = Invoke-Command -ComputerName $ComputerName -ScriptBlock { (Get-ItemProperty 'HKLM:\System\CurrentControlSet\Control\Terminal Server').fDenyTSConnections }
 return [PSCustomObject]@{ Computer=$ComputerName; PortOpen=$tcp.TcpTestSucceeded; ServiceRunning=($svc.Status -eq 'Running'); RDPEnabled=($reg -eq 0) }
}

function Get-RemoteAutoRunKeys {
 param([string]$ComputerName)
 $paths = @(
  'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
  'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
  'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'
 )
 $results = foreach ($path in $paths) {
  Invoke-Command -ComputerName $ComputerName -ScriptBlock {
   param($p)
   Get-ItemProperty -Path $p -ErrorAction SilentlyContinue | Select-Object PSChildName, *
  } -ArgumentList $path
 }
 return $results
}

function Verify-KerberosDelegation {
 param([string]$SearchBase, [string]$DelegationType = "Unconstrained")
 if ($DelegationType -eq "Unconstrained") {
  Get-ADObject -Filter 'userAccountControl -band 0x80000' -SearchBase $SearchBase -Properties TrustedForDelegation, Name, ObjectClass
 } else {
  Get-ADObject -Filter 'msDS-AllowedToDelegateTo -like "*"' -SearchBase $SearchBase -Properties 'msDS-AllowedToDelegateTo', Name, ObjectClass
 }
}

public static bool RemoteFileCopyStream(string localFilePath, string remoteComputer, string remoteFilePath, NetworkCredential credential = null) {
 try {
  var options = new ConnectionOptions();
  if (credential != null) { options.Username = credential.UserName; options.Password = credential.Password; }
  var scope = new ManagementScope($"\\\\{remoteComputer}\\root\cimv2", options);
  scope.Connect();
  // Note: En production, utiliser une méthode d'encodage Base64 via WMI ou un endpoint WinRM dédié pour le transfert de fichiers sécurisé.
  // Cette implémentation est un squelette pour l'architecture DSI.
  WriteLog($"Flux de copie sécurisé initié vers {remoteComputer}");
  return true;
 } catch (Exception ex) {
  WriteLog($"Échec copie flux : {ex.Message}", "ERROR");
  return false;
 }
}

function Generate-LateralMovementReport {
 param([string[]]$ComputerList, [string]$OutputPath)
 $data = foreach ($pc in $ComputerList) {
  $admin = (Audit-RemoteLocalAdmins -ComputerList @($pc)).Count
  $rdp = (Test-RemoteRDPAccess -ComputerName $pc).PortOpen
  [PSCustomObject]@{ Computer=$pc; RogueAdmins=$admin; RDPPortOpen=$rdp; AuditDate=(Get-Date) }
 }
 $data | ConvertTo-Html -Title "Rapport Audit Mouvement Latéral DSI" -CssUri "style.css" | Out-File $OutputPath
 Write-SysLog -Message "Rapport généré : $OutputPath" -Level 'INFO'
 return $OutputPath
}

function Deploy-RemoteScript {
 param([string]$ComputerName, [string]$ScriptUrl)
 $result = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  param($url)
  $code = (Invoke-WebRequest -Uri $url -UseBasicParsing).Content
  $sb = [ScriptBlock]::Create($code)
  & $sb
 } -ArgumentList $ScriptUrl
 Write-SysLog "DEPLOY_REMOTE: $ComputerName | URL: $ScriptUrl" -Level 'AUDIT'
 return $result
}

function Get-RemoteCachedCredentials {
 param([string]$ComputerName)
 $result = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  $raw = cmdkey /list 2>&1
  $entries = @()
  $raw | Select-String 'Target:' | ForEach-Object {
   $entries += [PSCustomObject]@{ Target = ($_ -replace '.*Target:\s*','').Trim() }
  }
  return $entries
 }
 Write-SysLog "AUDIT_CACHED_CREDS: $ComputerName | $($result.Count) entrée(s)" -Level 'AUDIT'
 return $result
}

function Check-RemoteLSASSProtection {
 param([string]$ComputerName)
 $val = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -ErrorAction SilentlyContinue).RunAsPPL
 }
 $protected = ($val -eq 1)
 Write-SysLog "CHECK_LSAASS_PPL: $ComputerName | Protected=$protected" -Level 'AUDIT'
 return $protected
}

function Modify-RemoteServiceBinary {
 param([string]$ComputerName, [string]$ServiceName, [string]$NewBinaryPath)
 try {
  $result = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
   param($svc, $bin)
   sc.exe config $svc binPath= "$bin"
  } -ArgumentList $ServiceName, $NewBinaryPath
  Write-SysLog "MODIFY_SVC_BIN: $ComputerName | $ServiceName -> $NewBinaryPath" -Level 'AUDIT'
  return $true
 } catch {
  Write-SysLog "ECHEC_MODIFY_SVC: $ComputerName | $_" -Level 'ERROR'
  return $false
 }
}

function Audit-RemoteAdminShares {
 param([string]$ComputerName)
 $shares = Get-CimInstance -ComputerName $ComputerName -ClassName Win32_Share |
  Where-Object { $_.Name -match 'C\$|ADMIN\$|IPC\$' }
 $result = $shares | ForEach-Object {
  [PSCustomObject]@{ Computer=$ComputerName; ShareName=$_.Name; Path=$_.Path; Description=$_.Description }
 }
 Write-SysLog "AUDIT_ADMIN_SHARES: $ComputerName | $($result.Count) partage(s)" -Level 'AUDIT'
 return $result
}

public static string Get-RemoteFileHash(string remotePath, string computerName) {
 string uncPath = $@"\\{computerName}\{remotePath.Replace(':', '$')}";
 using var stream = File.OpenRead(uncPath);
 using var sha256 = SHA256.Create();
 byte[] hashBytes = sha256.ComputeHash(stream);
 return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
}

function Search-RemoteFileSystem {
 param([string]$ComputerName, [string]$Pattern)
 $results = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  param($pat)
  Get-ChildItem -Path C:\ -Recurse -Include $pat -ErrorAction SilentlyContinue |
   Select-Object FullName, Length, LastWriteTime
 } -ArgumentList $Pattern
 Write-SysLog "SEARCH_FS: $ComputerName | Pattern=$Pattern | $($results.Count) fichier(s)" -Level 'AUDIT'
 return $results
}

function Wipe-RemoteTempDirectory {
 param([string]$ComputerName)
 $count = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  $files = Get-ChildItem -Path $env:TEMP -Recurse -ErrorAction SilentlyContinue
  $n = $files.Count
  $files | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
  return $n
 }
 Write-SysLog "WIPE_TEMP: $ComputerName | $count élément(s) supprimé(s)" -Level 'INFO'
 return $count
}

function Scan-RemoteOpenPorts {
 param([string]$ComputerName, [int[]]$Ports = @(445,135,5985,3389))
 $results = foreach ($port in $Ports) {
  $test = Test-NetConnection -ComputerName $ComputerName -Port $port -WarningAction SilentlyContinue
  [PSCustomObject]@{ Computer=$ComputerName; Port=$port; Open=$test.TcpTestSucceeded }
 }
 Write-SysLog "SCAN_PORTS: $ComputerName | Ports=$($Ports -join ',')" -Level 'AUDIT'
 return $results
}

function Get-RemoteActiveConnections {
 param([string]$ComputerName)
 $result = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  Get-NetTCPConnection -State Established | Select-Object LocalAddress,LocalPort,RemoteAddress,RemotePort,State,OwningProcess
 }
 Write-SysLog "NETSTAT_REMOTE: $ComputerName | $($result.Count) connexion(s)" -Level 'AUDIT'
 return $result
}

function Audit-RemoteFirewallRules {
 param([string]$ComputerName)
 $rules = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  Get-NetFirewallRule -Direction Inbound -Action Allow -Enabled True |
   Select-Object DisplayName, Profile, @{N='LocalPort';E={(($_ | Get-NetFirewallPortFilter).LocalPort) -join ','}}
 }
 Write-SysLog "AUDIT_FW_RULES: $ComputerName | $($rules.Count) règle(s)" -Level 'AUDIT'
 return $rules
}

function Set-RemoteRegistryKey {
 param([string]$ComputerName, [string]$Path, [string]$Name, [string]$Value)
 try {
  Invoke-Command -ComputerName $ComputerName -ScriptBlock {
   param($p,$n,$v)
   Set-ItemProperty -Path $p -Name $n -Value $v -Force -ErrorAction Stop
  } -ArgumentList $Path, $Name, $Value
  Write-SysLog "SET_REG: $ComputerName | $Path\$Name = $Value" -Level 'AUDIT'
  return $true
 } catch {
  Write-SysLog "ECHEC_SET_REG: $ComputerName | $_" -Level 'ERROR'
  return $false
 }
}

function Get-RemoteGroupPolicy {
 param([string]$ComputerName)
 $gpupdate = Invoke-Command -ComputerName $ComputerName -ScriptBlock { gpupdate /force /wait:0 2>&1 }
 $rsop = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  Get-GPResultantSetOfPolicy -ReportType Html -Path "$env:TEMP\rsop.html" -ErrorAction SilentlyContinue
  Get-Content "$env:TEMP\rsop.html" -Raw -ErrorAction SilentlyContinue
 }
 Write-SysLog "GPUPDATE_RSOP: $ComputerName" -Level 'AUDIT'
 return [PSCustomObject]@{ Computer=$ComputerName; GpUpdateOutput=$gpupdate; RSOP=$rsop }
}

function Check-RemoteDefenderExclusions {
 param([string]$ComputerName)
 $excl = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  $p = Get-MpPreference -ErrorAction SilentlyContinue
  [PSCustomObject]@{
   ExclusionPaths      = $p.ExclusionPath
   ExclusionExtensions = $p.ExclusionExtension
   ExclusionProcesses  = $p.ExclusionProcess
  }
 }
 Write-SysLog "DEFENDER_EXCL: $ComputerName | Chemins=$($excl.ExclusionPaths.Count)" -Level 'AUDIT'
