}

function Test-ADReplicationLateral {
 param([string]$DomainController)
 $result = Invoke-Command -ComputerName $DomainController -ScriptBlock {
  $repl = Get-ADReplicationPartnerMetadata -Target $env:COMPUTERNAME -ErrorAction SilentlyContinue
  [PSCustomObject]@{ Partner=$repl.Partner; LastReplication=$repl.LastReplicationSuccess; ConsecutiveFailures=$repl.ConsecutiveReplicationFailures }
 }
 Write-SysLog "AD_REPL_CHECK: $DomainController" -Level 'AUDIT'
 return $result
}

function Check-RemoteComputerAccountPasswordAge {
 param([string]$ComputerName)
 $pwdLastSet = (Get-ADComputer -Identity $ComputerName -Properties PasswordLastSet -ErrorAction Stop).PasswordLastSet
 $age = ((Get-Date) - $pwdLastSet).Days
 if ($age -gt 30) {
  Write-SysLog "PWD_AGE_WARN: $ComputerName | ${age} jours (> 30)" -Level 'WARN'
 } else {
  Write-SysLog "PWD_AGE_OK: $ComputerName | ${age} jours" -Level 'INFO'
 }
 return $age
}

function Audit-RemoteDelegatedAdmins {
 param([string]$ComputerName)
 $dn  = (Get-ADComputer -Identity $ComputerName -ErrorAction Stop).DistinguishedName
 $acl = (Get-Acl "AD:\$dn").Access | Where-Object {
  $_.ActiveDirectoryRights -match 'GenericAll|WriteProperty|WriteDacl|WriteOwner' -and
  $_.AccessControlType -eq 'Allow'
 } | Select-Object IdentityReference, ActiveDirectoryRights
 Write-SysLog "DELEGATED_ADMINS: $ComputerName | $($acl.Count) entrée(s)" -Level 'AUDIT'
 return $acl
}

function Collect-RemoteMemoryDump {
 param([string]$ComputerName, [string]$ProcessName, [string]$OutputPath)
 $result = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  param($proc, $out)
  $procdump = 'C:\Tools\procdump.exe'
  if (-not (Test-Path $procdump)) { throw 'procdump.exe introuvable dans C:\Tools\' }
  & $procdump -accepteula -ma $proc $out
 } -ArgumentList $ProcessName, $OutputPath
 Write-SysLog "MEM_DUMP: $ComputerName | $ProcessName -> $OutputPath" -Level 'AUDIT'
 return ($result -match 'Dump count reached')
}

function Get-RemotePrefetchFiles {
 param([string]$ComputerName)
 $files = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  Get-ChildItem 'C:\Windows\Prefetch' -Filter '*.pf' -ErrorAction SilentlyContinue |
   Select-Object Name, Length, LastWriteTime
 }
 Write-SysLog "PREFETCH: $ComputerName | $($files.Count) fichier(s)" -Level 'INFO'
 return $files
}

function Audit-RemoteRDPBitmapCache {
 param([string]$ComputerName)
 $info = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  $cachePath = "$env:LOCALAPPDATA\Microsoft\Terminal Server Client\Cache"
  $items = Get-ChildItem $cachePath -ErrorAction SilentlyContinue
  [PSCustomObject]@{ CachePath=$cachePath; FileCount=$items.Count; TotalSizeMB=[math]::Round(($items | Measure-Object Length -Sum).Sum/1MB,2) }
 }
 Write-SysLog "RDP_BITMAP_CACHE: $ComputerName | $($info.FileCount) fichier(s) / $($info.TotalSizeMB) MB" -Level 'INFO'
 return $info
}

public static uint RemoteWMIExecute(string computerName, string className, string methodName, Dictionary<string, object> args) {
 var scope = new ManagementScope($@"\\{computerName}\root\cimv2");
 scope.Connect();
 using var mc = new ManagementClass(scope, new ManagementPath(className), null);
 ManagementBaseObject inParams = mc.GetMethodParameters(methodName);
 foreach (var kv in args) inParams[kv.Key] = kv.Value;
 ManagementBaseObject result = mc.InvokeMethod(methodName, inParams, null);
 return (uint)result["ReturnValue"];
}

public static object RemoteRegistryRead(string computerName, string hive, string keyPath, string valueName) {
 uint hiveId = hive.ToUpper() switch {
  "HKLM" => 0x80000002u,
  "HKCU" => 0x80000001u,
  "HKCR" => 0x80000000u,
  _      => 0x80000002u
 };
 var scope = new ManagementScope($@"\\{computerName}\root\default");
 scope.Connect();
 using var reg = new ManagementClass(scope, new ManagementPath("StdRegProv"), null);
 var inParams = reg.GetMethodParameters("GetStringValue");
 inParams["hDefKey"]    = hiveId;
 inParams["sSubKeyName"] = keyPath;
 inParams["sValueName"] = valueName;
 var result = reg.InvokeMethod("GetStringValue", inParams, null);
 return result["sValue"];
}

public static List<Dictionary<string, string>> RemoteProcessList(string computerName) {
 var results = new List<Dictionary<string, string>>();
 var scope   = new ManagementScope($@"\\{computerName}\root\cimv2");
 scope.Connect();
 var query    = new ObjectQuery("SELECT ProcessId, Name, ExecutablePath, CommandLine FROM Win32_Process");
 using var searcher = new ManagementObjectSearcher(scope, query);
 foreach (ManagementObject obj in searcher.Get()) {
  results.Add(new Dictionary<string, string> {
   ["PID"]            = obj["ProcessId"]?.ToString() ?? "",
   ["Name"]           = obj["Name"]?.ToString() ?? "",
   ["ExecutablePath"] = obj["ExecutablePath"]?.ToString() ?? "",
   ["CommandLine"]    = obj["CommandLine"]?.ToString() ?? ""
  });
 }
 return results;
}

public static bool Validate-RemoteCertificateTrust(string computerName, int port) {
 bool trusted = false;
 var client = new System.Net.Sockets.TcpClient();
 try {
  client.Connect(computerName, port);
  using var sslStream = new System.Net.Security.SslStream(client.GetStream(), false,
   (sender, cert, chain, errors) => { trusted = (errors == System.Net.Security.SslPolicyErrors.None); return true; });
  sslStream.AuthenticateAsClient(computerName);
 } catch (Exception ex) {
  WriteLog($"Validate-RemoteCertificateTrust: {computerName}:{port} | {ex.Message}", "ERROR");
 } finally {
  client.Close();
 }
 return trusted;
}

function Check-RemoteBitLockerStatus {
 param([string]$ComputerName)
 $status = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  Get-BitLockerVolume -ErrorAction SilentlyContinue | Select-Object MountPoint, VolumeStatus, EncryptionPercentage, KeyProtector
 }
 Write-SysLog "BITLOCKER: $ComputerName | $($status.Count) volume(s)" -Level 'INFO'
 return $status
}

function Invoke-RemoteWMIEventSubscription {
 param([string]$ComputerName)
 $subs = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  $ns = 'root\subscription'
  $filters   = Get-CimInstance -Namespace $ns -ClassName __EventFilter -ErrorAction SilentlyContinue
  $consumers = Get-CimInstance -Namespace $ns -ClassName CommandLineEventConsumer -ErrorAction SilentlyContinue
  [PSCustomObject]@{ Filters=$filters; Consumers=$consumers }
 }
 Write-SysLog "WMI_EVENT_SUBS: $ComputerName | $($subs.Filters.Count) filtre(s)" -Level 'AUDIT'
 return $subs
}

function Get-RemoteCOMHijacking {
 param([string]$ComputerName)
 $suspicious = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  $hkcu = Get-ChildItem 'HKCU:\Software\Classes\CLSID' -ErrorAction SilentlyContinue |
   Where-Object { Test-Path "$($_.PSPath)\InprocServer32" } |
   ForEach-Object {
    $srv = (Get-ItemProperty "$($_.PSPath)\InprocServer32" -ErrorAction SilentlyContinue).'(default)'
    [PSCustomObject]@{ CLSID=$_.PSChildName; DLL=$srv; Hive='HKCU' }
   }
  $hkcu
 }
 Write-SysLog "COM_HIJACK: $ComputerName | $($suspicious.Count) entrée(s) HKCU CLSID" -Level 'AUDIT'
 return $suspicious
}

function Audit-RemotePrintSpooler {
 param([string]$ComputerName, [switch]$DisableIfRunning)
 $svc = Get-Service -ComputerName $ComputerName -Name 'Spooler' -ErrorAction SilentlyContinue
 $running = ($svc.Status -eq 'Running')
 if ($DisableIfRunning -and $running) {
  Invoke-Command -ComputerName $ComputerName -ScriptBlock {
   Stop-Service Spooler -Force
   Set-Service  Spooler -StartupType Disabled
  }
  Write-SysLog "SPOOLER_DISABLED: $ComputerName" -Level 'AUDIT'
 } else {
  Write-SysLog "SPOOLER_STATUS: $ComputerName | Running=$running" -Level 'INFO'
 }
 return [PSCustomObject]@{ Computer=$ComputerName; SpoolerRunning=$running; DisabledNow=($DisableIfRunning -and $running) }
}

function Check-RemoteNTLMv1Usage {
 param([string]$ComputerName)
 $lmLevel = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
  (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -ErrorAction SilentlyContinue).LmCompatibilityLevel
 }
 $disabled = ($lmLevel -ge 3)
 if (-not $disabled) {
  Write-SysLog "NTLMV1_RISK: $ComputerName | LmCompatibilityLevel=$lmLevel (NTLMv1 possible)" -Level 'WARN'
 } else {
  Write-SysLog "NTLMV1_OK: $ComputerName | LmCompatibilityLevel=$lmLevel" -Level 'INFO'
 }
 return $disabled
}

public static List<string> Get-RemoteLoggedOnUsers(string computerName) {
 var users   = new List<string>();
 var scope   = new ManagementScope($@"\\{computerName}\root\cimv2");
 scope.Connect();
 var query   = new ObjectQuery("SELECT * FROM Win32_LoggedOnUser");
 using var searcher = new ManagementObjectSearcher(scope, query);
 foreach (ManagementObject obj in searcher.Get()) {
  var account = new ManagementObject(obj["Antecedent"].ToString());
  string name   = account["Name"]?.ToString() ?? "";
  string domain = account["Domain"]?.ToString() ?? "";
  if (!string.IsNullOrEmpty(name)) users.Add($"{domain}\\{name}");
 }
 return users.Distinct().ToList();
}

function Invoke-RemoteCleanup {
 param([string]$ComputerName)
 try {
  Invoke-Command -ComputerName $ComputerName -ScriptBlock {
   # Vider le répertoire temporaire
   Get-ChildItem $env:TEMP -Recurse -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
   # Effacer l'historique PowerShell
   $histPath = (Get-PSReadLineOption).HistorySavePath
   if (Test-Path $histPath) { Clear-Content $histPath -Force }
   # Supprimer les fichiers de log temporaires DSI
   Remove-Item "$env:TEMP\DSI_SysLog.txt" -Force -ErrorAction SilentlyContinue
  }
  Write-SysLog "CLEANUP_OK: $ComputerName" -Level 'AUDIT'
  return $true
 } catch {
  Write-SysLog "CLEANUP_FAIL: $ComputerName | $_" -Level 'ERROR'
  return $false
 }
}
